test('invoiceTotals returns vat in the result', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1, discountPercent: 0 }],
  }).value;

  const totals = invoiceTotals(invoice);
  assert.ok('vat' in totals);
  assert.equal(typeof totals.vat, 'number');
});

test('invoiceTotals calculates VAT correctly with 21% rate', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1, discountPercent: 0 }],
  }).value;

  // DES-HOUR: 1 * 8500 = 8500 cents (no discount)
  // VAT: 8500 * 21 / 100 = 1785 cents
  const totals = invoiceTotals(invoice);
  assert.equal(totals.vat, 1785);
});

test('invoiceTotals calculates VAT on amount after discount', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 2, discountPercent: 10 }],
  }).value;

  // DES-HOUR: 2 * 8500 = 17000
  // Discount: 17000 * 10 / 100 = 1700
  // Amount after discount: 17000 - 1700 = 15300
  // VAT: 15300 * 21 / 100 = 3213 cents
  const totals = invoiceTotals(invoice);
  assert.equal(totals.vat, 3213);
});

test('invoiceTotals with multiple lines sums VAT correctly', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DES-HOUR', name: 'Design work (hour)', qty: 1, unitPrice: 8500, vatRate: 21, discountPercent: 0 },
      { sku: 'DEV-HOUR', name: 'Development (hour)', qty: 1, unitPrice: 9500, vatRate: 9, discountPercent: 0 },
    ],
  };

  // Line 1: 8500 * 21 / 100 = 1785
  // Line 2: 9500 * 9 / 100 = 855
  // Total VAT: 2640
  const totals = invoiceTotals(invoice);
  assert.equal(totals.vat, 2640);
});

test('invoiceTotals with 0% VAT rate', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'STICKER', name: 'Sticker pack', qty: 10, unitPrice: 100, vatRate: 0, discountPercent: 0 },
    ],
  };

  const totals = invoiceTotals(invoice);
  assert.equal(totals.vat, 0);
});

test('invoiceTotals total includes VAT', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1, discountPercent: 0 }],
  }).value;

  const totals = invoiceTotals(invoice);
  // subtotal: 8500, vat: 1785, no discount
  // total: 8500 + 1785 = 10285
  assert.equal(totals.total, totals.subtotal + totals.vat);
});

test('invoiceTotals with discount and VAT', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 2, discountPercent: 10 }],
  }).value;

  const totals = invoiceTotals(invoice);
  // subtotal: 17000
  // discount: 1700
  // amount after discount: 15300
  // vat: 15300 * 21 / 100 = 3213
  // total: 17000 - 1700 + 3213 = 18513
  assert.equal(totals.subtotal, 17000);
  assert.equal(totals.discount, 1700);
  assert.equal(totals.vat, 3213);
  assert.equal(totals.total, 18513);
});

test('invoiceTotals VAT is rounded per line', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'TEST', name: 'Test item', qty: 1, unitPrice: 100, vatRate: 21, discountPercent: 0 },
    ],
  };

  // 100 * 21 / 100 = 21 cents (should round to 21)
  const totals = invoiceTotals(invoice);
  assert.equal(totals.vat, 21);
});

test('invoiceTotals formula: total = subtotal - discount + vat', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DES-HOUR', name: 'Design work (hour)', qty: 2, unitPrice: 8500, vatRate: 21, discountPercent: 10 },
      { sku: 'DEV-HOUR', name: 'Development (hour)', qty: 1, unitPrice: 9500, vatRate: 9, discountPercent: 5 },
    ],
  };

  const totals = invoiceTotals(invoice);
  // DES-HOUR: 17000 - 1700 = 15300, VAT: 3213
  // DEV-HOUR: 9500 - 475 = 9025, VAT: 812 (9025 * 9 / 100 = 812.25 -> 812)
  // subtotal: 26500, discount: 2175, vat: 4025
  // total: 26500 - 2175 + 4025 = 28350
  assert.equal(totals.total, totals.subtotal - totals.discount + totals.vat);
});

