import test from 'node:test';
import assert from 'node:assert/strict';
import { renderInvoiceText } from '../src/render.js';
import { createInvoice, issueInvoice } from '../src/invoices.js';

test('renderInvoiceText returns a string', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 2, discountPercent: 0 }],
  }).value;

  const result = renderInvoiceText(invoice);
  assert.equal(typeof result, 'string');
});

test('renderInvoiceText shows DRAFT for draft invoices', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 2, discountPercent: 0 }],
  }).value;

  const result = renderInvoiceText(invoice);
  assert.match(result, /^DRAFT/);
});

test('renderInvoiceText shows invoice number when issued', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 2, discountPercent: 0 }],
  }).value;

  const issued = issueInvoice(invoice, []).value;
  const result = renderInvoiceText(issued);
  assert.match(result, /^INV-2026-0001/);
});

test('renderInvoiceText includes customer name', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 2, discountPercent: 0 }],
  }).value;

  const result = renderInvoiceText(invoice);
  const lines = result.split('\n');
  assert.match(lines[1], /[A-Z]/); // customer name should be on line 2
});

test('renderInvoiceText includes all line items', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DES-HOUR', qty: 2, discountPercent: 0 },
      { sku: 'DEV-HOUR', qty: 3, discountPercent: 0 },
    ],
  }).value;

  const result = renderInvoiceText(invoice);
  assert.match(result, /Design work/);
  assert.match(result, /Development/);
  assert.match(result, /2x/);
  assert.match(result, /3x/);
});

test('renderInvoiceText shows quantities', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5, discountPercent: 0 }],
  }).value;

  const result = renderInvoiceText(invoice);
  assert.match(result, /5x/);
});

test('renderInvoiceText formats amounts as euros', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 2, discountPercent: 0 }],
  }).value;

  const result = renderInvoiceText(invoice);
  assert.match(result, /€\d+\.\d{2}/);
});

test('renderInvoiceText shows unit price', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1, discountPercent: 0 }],
  }).value;

  const result = renderInvoiceText(invoice);
  // DES-HOUR costs 8500 cents = €85.00
  assert.match(result, /€85\.00/);
});

test('renderInvoiceText shows line totals', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 2, discountPercent: 0 }],
  }).value;

  const result = renderInvoiceText(invoice);
  // 2 * €85.00 = €170.00
  assert.match(result, /€170\.00/);
});

test('renderInvoiceText includes Total line', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 2, discountPercent: 0 }],
  }).value;

  const result = renderInvoiceText(invoice);
  assert.match(result, /Total: €\d+\.\d{2}/);
});

test('renderInvoiceText calculates correct total', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DES-HOUR', qty: 2, discountPercent: 0 },
      { sku: 'DEV-HOUR', qty: 3, discountPercent: 0 },
    ],
  }).value;

  const result = renderInvoiceText(invoice);
  // DES-HOUR: 2 * 8500 = 17000
  // DEV-HOUR: 3 * 9500 = 28500
  // Total: 45500 = €455.00
  assert.match(result, /Total: €455\.00/);
});

test('renderInvoiceText with a single line item', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'STICKER', qty: 100, discountPercent: 0 }],
  }).value;

  const result = renderInvoiceText(invoice);
  const lines = result.split('\n');
  assert.equal(lines.length, 4); // header + customer + 1 line item + total
  assert.match(result, /100x/);
});

test('renderInvoiceText with multiple line items', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DES-HOUR', qty: 2, discountPercent: 0 },
      { sku: 'DEV-HOUR', qty: 3, discountPercent: 0 },
      { sku: 'COPY-HOUR', qty: 1, discountPercent: 0 },
    ],
  }).value;

  const result = renderInvoiceText(invoice);
  const lines = result.split('\n');
  assert.equal(lines.length, 6); // header + customer + 3 line items + total
  assert.match(result, /Design work/);
  assert.match(result, /Development/);
  assert.match(result, /Copywriting/);
});

test('renderInvoiceText uses correct customer name', () => {
  const invoice = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1, discountPercent: 0 }],
  }).value;

  const result = renderInvoiceText(invoice);
  const lines = result.split('\n');
  assert.equal(lines[1], 'Kite & Co');
});

test('renderInvoiceText handles unknown customer gracefully', () => {
  const invoice = {
    customerId: 'C-999',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', name: 'Design work (hour)', qty: 1, unitPrice: 8500, vatRate: 21 }],
  };

  const result = renderInvoiceText(invoice);
  assert.match(result, /Unknown Customer/);
});

test('renderInvoiceText output is multiline', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 2, discountPercent: 0 }],
  }).value;

  const result = renderInvoiceText(invoice);
  const lines = result.split('\n');
  assert.ok(lines.length >= 4); // at least header, customer, line item, total
});

test('renderInvoiceText shows discount when discount > 0', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 2, discountPercent: 10 }],
  }).value;

  const result = renderInvoiceText(invoice);
  assert.match(result, /Subtotal:/);
  assert.match(result, /Discount:/);
});

test('renderInvoiceText does not show subtotal/discount when discount = 0', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 2, discountPercent: 0 }],
  }).value;

  const result = renderInvoiceText(invoice);
  assert.ok(!result.includes('Subtotal:'));
  assert.ok(!result.includes('Discount:'));
});

test('renderInvoiceText with discount has correct structure', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 2, discountPercent: 10 }],
  }).value;

  const result = renderInvoiceText(invoice);
  const lines = result.split('\n');
  // header + customer + 1 line item + subtotal + discount + total
  assert.equal(lines.length, 6);
  assert.match(lines[0], /^DRAFT/);
  assert.match(lines[3], /Subtotal:/);
  assert.match(lines[4], /Discount:/);
  assert.match(lines[5], /^Total:/);
});

test('renderInvoiceText shows correct discount amount', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 2, discountPercent: 10 }],
  }).value;

  const result = renderInvoiceText(invoice);
  // 2 * 8500 = 17000, discount = 1700 = €17.00
  assert.match(result, /Discount: -€17\.00/);
});

test('renderInvoiceText with multiple discounts shows combined discount', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DES-HOUR', qty: 2, discountPercent: 10 },
      { sku: 'DEV-HOUR', qty: 1, discountPercent: 20 },
    ],
  }).value;

  const result = renderInvoiceText(invoice);
  // DES-HOUR discount: 17000 * 0.1 = 1700
  // DEV-HOUR discount: 9500 * 0.2 = 1900
  // Total discount: 3600 = €36.00
  assert.match(result, /Discount: -€36\.00/);
  assert.match(result, /Total: €229\.00/);
});

test('renderInvoiceText shows VAT when present', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1, discountPercent: 0 }],
  }).value;

  const result = renderInvoiceText(invoice);
  assert.match(result, /VAT: €\d+\.\d{2}/);
});

test('renderInvoiceText does not show VAT when zero', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'STICKER', name: 'Sticker pack', qty: 1, unitPrice: 100, vatRate: 0, discountPercent: 0 }],
  };

  const result = renderInvoiceText(invoice);
  assert.ok(!result.includes('VAT:'));
});

test('renderInvoiceText shows correct VAT amount', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1, discountPercent: 0 }],
  }).value;

  const result = renderInvoiceText(invoice);
  // DES-HOUR: 8500, VAT: 8500 * 21 / 100 = 1785 = €17.85
  assert.match(result, /VAT: €17\.85/);
});

test('renderInvoiceText VAT appears before total', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1, discountPercent: 0 }],
  }).value;

  const result = renderInvoiceText(invoice);
  const lines = result.split('\n');
  const vatIndex = lines.findIndex((line) => line.startsWith('VAT:'));
  const totalIndex = lines.findIndex((line) => line.startsWith('Total:'));
  assert.ok(vatIndex >= 0);
  assert.ok(totalIndex > vatIndex);
});

test('renderInvoiceText shows subtotal when VAT present but no discount', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1, discountPercent: 0 }],
  }).value;

  const result = renderInvoiceText(invoice);
  assert.match(result, /Subtotal:/);
  assert.ok(!result.includes('Discount:'));
});

test('renderInvoiceText with VAT and discount shows all lines', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 2, discountPercent: 10 }],
  }).value;

  const result = renderInvoiceText(invoice);
  const lines = result.split('\n');
  // header + customer + 1 item + subtotal + discount + vat + total
  assert.equal(lines.length, 7);
  assert.match(lines[3], /Subtotal:/);
  assert.match(lines[4], /Discount:/);
  assert.match(lines[5], /VAT:/);
  assert.match(lines[6], /^Total:/);
});

test('renderInvoiceText calculates correct total with VAT', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1, discountPercent: 0 }],
  }).value;

  const result = renderInvoiceText(invoice);
  // subtotal: 8500, vat: 1785, total: 10285 = €102.85
  assert.match(result, /Total: €102\.85/);
});

