    issueDate: '2026-10-07',
    lines: [
      { sku: 'DES-HOUR', qty: 2, discountPercent: 10 },
      { sku: 'DEV-HOUR', qty: 1, discountPercent: 20 },
    ],
  }).value;

  // DES-HOUR: 2 * 8500 = 17000, discount = 1700, amount = 15300, VAT = 3213
  // DEV-HOUR: 1 * 9500 = 9500, discount = 1900, amount = 7600, VAT = 684
  // Total VAT: 3897
  // Total: 26500 - 3600 + 3897 = 26797
  const totals = invoiceTotals(invoice);
  assert.equal(totals.subtotal, 26500);
  assert.equal(totals.discount, 3600);
  assert.equal(totals.vat, 3897);
  assert.equal(totals.total, 26797);
});

